cd /workspace && python3 - <<'EOF'
import time, random
from collections import Counter
rng=random.Random(0)
for n in (2, 8, 32):
    data=[[rng.randrange(10**9) for _ in range(n)] for _ in range(20000)]
    t0=time.time()
    for d in data: c=Counter(d)
    t1=time.time()
    for d in data:
        c={}
        for v in d: c[v]=c.get(v,0)+1
    t2=time.time()
    for d in data:
        c={}
        get=c.get
        for v in d: c[v]=get(v,0)+1
    t3=time.time()
    print(n, 'Counter %.4f dictloop %.4f dictloop-get %.4f' % (t1-t0, t2-t1, t3-t2))
EOF
